-- Plano de Virada — 04/11/2026 · Spec: docs/specs/2026-11-04-aba-plano-virada.md
-- JÁ APLICADO no Supabase (migration plano_virada_v1). Idempotente.
-- Mesmo padrão das outras tabelas do cockpit: RLS ligado sem policy; o Flask
-- (DATABASE_URL) é o único caminho de leitura e escrita.

create table if not exists cockpit.virada_planos (
  customer text primary key,
  data_virada date not null,
  data_go_nogo date,
  data_congelamento date,
  data_corte date,
  fim_assistida date,
  recomendacao text,
  janelas jsonb not null default '[]'::jsonb,
  updated_by text,
  updated_at timestamptz not null default now()
);

create table if not exists cockpit.virada_itens (
  id bigint generated by default as identity primary key,
  customer text not null,
  codigo text not null,
  fase text not null check (fase in ('preparacao','testes','go_nogo','congelamento','corte','carga','dia_d','assistida','fechamento')),
  frente text not null,
  atividade text not null,
  detalhe text,
  resp_lado text not null default 'TOTVS' check (resp_lado in ('TOTVS','CLIENTE','AMBOS')),
  resp_nome text,
  data_inicio date,
  data_fim date,
  status text not null default 'planejado' check (status in ('planejado','em_andamento','concluido','bloqueado','cancelado')),
  criticidade text not null default 'media' check (criticidade in ('alta','media','baixa')),
  criterio_go boolean not null default false,
  dependencia text,
  referencia text,
  observacao text,
  origem text not null default 'manual' check (origem in ('historico','manual')),
  ordem int not null default 0,
  ativo boolean not null default true,
  created_by text, updated_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (customer, codigo),
  check (data_inicio is null or data_fim is null or data_fim >= data_inicio)
);
create index if not exists virada_itens_customer on cockpit.virada_itens (customer, ativo, fase);

alter table cockpit.virada_planos enable row level security;
alter table cockpit.virada_itens enable row level security;

-- ── Carga inicial DIGITRO (000348D0) a partir do histórico do projeto ───────
-- Fontes: comitê de gestão 14/10, reuniões 01–23/10, inventário de e-mails do
-- CP 28/10, Radar 30/10, dossiê de transição 03/11, respostas devidas 04/11.
insert into cockpit.virada_planos (customer, data_virada, data_go_nogo, data_congelamento, data_corte, fim_assistida, recomendacao, janelas, updated_by)
values ('000348D0', '2027-01-04', '2026-12-01', '2026-12-02', '2026-12-31', '2027-01-29',
 'Virada em 04/01/2027 (segunda), com corte do Datasul em 31/12/2026 e carga dos saldos entre 01 e 03/01, quando a empresa não opera (feriado + fim de semana). É o único período que começa o Protheus junto com o exercício contábil e com a CBS plena: PIS/COFINS deixam de existir em 01/01/2027, então o Datasul não precisa ser adaptado à Reforma e a ECD/ECF de 2026 fecham inteiras no legado. Condição: Go/No-Go aprovado em 01/12 e calendário de recesso da Dígitro confirmado. Plano B: 01/02/2027.',
 '[
  {"periodo":"Virada em 04/01/2027 (seg)","avaliacao":"recomendado","pros":"Começa com o exercício de 2027: saldos de abertura em 31/12, ECD/ECF 2026 inteiras no Datasul, sem saldo mensal no meio do ano. CBS plena e fim do PIS/COFINS em 01/01: a Reforma roda só no Protheus. Corte com 3,5 dias sem operação (31/12 à tarde a 03/01). Data já usada como marco no projeto.","contras":"Pouca folga: Go/No-Go em 01/12 e recesso de fim de ano encurtam dezembro. Alíquota da CBS só sai até 15/12. Fechamento de dezembro no Datasul acontece com o Protheus já rodando."},
  {"periodo":"Virada em 01/02/2027 (seg) — plano B","avaliacao":"alternativa","pros":"Mais 4 semanas para cadastros, Custos/GGF, Comissões e CNAB. Janeiro vira um 3º ciclo de testes com dados reais.","contras":"Janeiro inteiro no Datasul sob a CBS: exige adaptar o legado à Reforma. Saldos de abertura em 31/01 (meio do exercício), ECD 2027 em dois sistemas, apuração de janeiro no legado. Carnaval em 08–09/02 cai na operação assistida."},
  {"periodo":"Virada em dezembro/2026","avaliacao":"evitar","pros":"Nenhuma vantagem real.","contras":"Parte o exercício de 2026 em dois sistemas, coincide com 13º, fechamento anual e faturamento de fim de ano dos contratos públicos, e obrigaria parametrizar PIS/COFINS para um único mês."},
  {"periodo":"Virada em março/2027 ou depois","avaliacao":"evitar","pros":"Folga ampla de prazo.","contras":"Mais um trimestre do Datasul sob a CBS, custo de manter duas equipes e risco de desmobilizar os usuários-chave já capacitados. Sai do marco acordado na Ata de 17/08."}
 ]'::jsonb, 'Claude (carga inicial)')
on conflict (customer) do nothing;

